function sorter(items,bins,intro){return{items,bins,intro,html:()=>'<p>'+intro+'</p><div class="card" style="text-align:center"><div class="txt" id="sit" style="font-family:Cairo;font-size:24px;font-weight:800"></div></div><div class="chips" style="justify-content:center" id="sb">'+bins.map(b=>'<button class="chip" data-b="'+esc(b)+'">'+esc(b)+'</button>').join('')+'</div><div class="readout" id="sr" style="margin-top:10px">صنّف '+AR(items.length)+' عناصر.</div>',
 init(){const it=shuffle(items);let i=0,ok=0;const show=()=>{A.$('#sit').textContent=i<it.length?it[i][0]:'انتهى التّصنيف';};show();A.$$('#sb .chip').forEach(b=>b.onclick=()=>{if(i>=it.length)return;const good=b.dataset.b===it[i][1];if(good)ok++;A.$('#sr').innerHTML=(good?'صحيح: ':'غير صحيح. الصّواب: ')+'«'+esc(it[i][0])+'» ← <b>'+esc(it[i][1])+'</b>'+(it[i][2]?' — '+esc(it[i][2]):'');i++;show();if(i===it.length){A.$('#sr').innerHTML+='<br>النّتيجة: '+AR(ok)+' من '+AR(it.length);S.done['lab:sort']=1;A.addXP(ok)}})}}}
