function stepper(svgf,steps){return{html:()=>'<div id="stv"></div><div class="readout" id="stt" style="margin-top:10px"></div><div class="row" style="margin-top:10px"><button class="btn alt" id="sp">السّابق</button><button class="btn" id="sn">التّالي</button><span class="mut" id="sc"></span></div>',
 init(){let i=0;const show=()=>{A.$('#stv').innerHTML=svgf(i);A.$('#stt').innerHTML='<b>'+steps[i][0]+'</b><br>'+steps[i][1];A.$('#sc').textContent=AR(i+1)+' / '+AR(steps.length);if(i===steps.length-1){S.done['lab:step']=1;A.save()}};A.$('#sn').onclick=()=>{i=(i+1)%steps.length;show()};A.$('#sp').onclick=()=>{i=(i-1+steps.length)%steps.length;show()};show()}}}
