SIM.static={html:()=>'<p>ادلك البالون بقطعة الصوف، ثم قرّبه من قصاصات الورق أو من بالون آخر مشحون.</p><div id="scv"></div><div class="ctl">'+rng('rub','عدد مرّات الدلك',0,10,0)+'<div class="chips" id="scm"><button class="chip on" data-m="p">قرّبه من قصاصات الورق</button><button class="chip" data-m="b">قرّبه من بالون مشحون مثله</button></div><div class="readout" id="sco"></div></div>',
 init(){let m='p';const d=()=>{const r=+A.$('#rub').value;A.$('#rubv').textContent=AR(r);let ch='';for(let i=0;i<r;i++)ch+='<text x="'+(150+(i%5)*18)+'" y="'+(110+Math.floor(i/5)*22)+'" font-size="18" fill="#2f7fb5">−</text>';
  let b='<ellipse cx="190" cy="115" rx="70" ry="85" fill="#f6a5a5" stroke="#b55"/>'+ch;if(m==='p'){for(let i=0;i<6;i++){const pull=r?Math.min(1,r/6):0;b+='<rect x="'+(420-pull*120+i*12)+'" y="'+(200-pull*(60+i*8))+'" width="12" height="8" fill="#fff" stroke="#999"/>'}}else{const gap=r?140+r*12:140;b+='<ellipse cx="'+(190+gap+60)+'" cy="115" rx="70" ry="85" fill="#f6a5a5" stroke="#b55"/>'+(r?ch.replace(/x="(\d+)/g,(s,x)=>'x="'+(+x+gap+60)):'')}
  A.$('#scv').innerHTML=sv(640,240,b);A.$('#sco').innerHTML=!r?'البالون متعادل (±): عدد الشحنات السالبة يساوي عدد الشحنات الموجبة.':m==='p'?'بالدلك تنتقل شحنات سالبة إلى البالون فيتكهرب ويجذب القصاصات الصغيرة.':'البالونان يحملان شحنة من النوع نفسه: <b>الشحنات المتشابهة تتنافر</b>.';S.done['lab:static']=100;A.save()};
  A.$$('#scm .chip').forEach(b=>b.onclick=()=>{A.$$('#scm .chip').forEach(c=>c.classList.remove('on'));b.classList.add('on');m=b.dataset.m;d()});A.$('#rub').oninput=d;d()}};
SIM.electroscope={html:()=>'<p>الكشّاف الكهربائي: قرص فلزّي، وساق فلزّية، وورقتان فلزّيتان، وعازل.</p><div class="chips" id="esm"><button class="chip on" data-m="0">بلا جسم مشحون</button><button class="chip" data-m="i">تقريب جسم سالب (الحثّ)</button><button class="chip" data-m="c">لمس القرص بجسم سالب</button><button class="chip" data-m="r">إبعاد الجسم بعد التقريب</button></div><div id="esv"></div><div class="readout" id="eso"></div>',
 init(){let charged=false;const d=m=>{if(m==='c')charged=true;if(m==='0')charged=false;const open=m==='i'||charged;const a=open?28:4;
  A.$('#esv').innerHTML=sv(640,260,'<rect x="250" y="80" width="140" height="170" rx="10" fill="rgba(170,210,240,.3)" stroke="#456"/><rect x="290" y="64" width="60" height="18" fill="#bbb"/><line x1="320" y1="40" x2="320" y2="170" stroke="#999" stroke-width="6"/><ellipse cx="320" cy="36" rx="40" ry="8" fill="#999"/><path d="M320 170 l'+(-a)+' 60 M320 170 l'+a+' 60" stroke="#d6a640" stroke-width="5"/>'+(m==='i'||m==='c'?'<rect x="'+(m==='c'?300:290)+'" y="'+(m==='c'?4:-10)+'" width="40" height="'+(m==='c'?26:20)+'" fill="#555"/><text x="320" y="'+(m==='c'?22:6)+'" text-anchor="middle" fill="#fff" font-size="16">−</text>':''));
  A.$('#eso').innerHTML={0:charged?'الكشّاف مشحون باللمس فتبقى الورقتان منفرجتين.':'الكشّاف متعادل: الورقتان منطبقتان.',i:'بالحثّ يكتسب القرص شحنة موجبة والورقتان شحنة سالبة فتنفرجان.',c:'الشحن باللمس: يكتسب الكشّاف شحنة سالبة ولا تزول بزوال التلامس.',r:charged?'شحنة اللمس لا تزول؛ الورقتان منفرجتان.':'تزول شحنة الحثّ بزوال المؤثّر فتنطبق الورقتان.'}[m];S.done['lab:electroscope']=100;A.save()};
  A.$$('#esm .chip').forEach(b=>b.onclick=()=>{A.$$('#esm .chip').forEach(c=>c.classList.remove('on'));b.classList.add('on');d(b.dataset.m)});d('0')}};
