const sl=(id,ids,f)=>({html:()=>'<div id="'+id+'v"></div><div class="ctl">'+ids.map(a=>rng(...a)).join('')+'<div class="readout" id="'+id+'o"></div></div>',init(){const d=()=>{const v={};ids.forEach(a=>{v[a[0]]=+A.$('#'+a[0]).value;A.$('#'+a[0]+'v').textContent=AR(v[a[0]])});const r=f(v);A.$('#'+id+'v').innerHTML=r[0];A.$('#'+id+'o').innerHTML=r[1];S.done['lab:'+id]=100;A.save()};ids.forEach(a=>A.$('#'+a[0]).oninput=d);d()}});
